-- ── 2.2 Briefing lembaga (hero + Cerita dari Tim + Suara Tim) ─────────────────────────
-- tema_esai dan cerita_pegawai dihitung dari jawaban esai 150 baris di bagian 1:
-- jumlah_mention adalah jumlah responden yang benar-benar memilih frasa/tema itu.
insert into public.briefing (sekolah_id, periode_id, modul, scope, scope_id, status, teks, sumber, catatan_internal, tema_esai, cerita_pegawai, draf_asal)
values ('YPS-FAMMI', '2026-07', 'sc', 'sekolah', 'YPS-FAMMI', 'disetujui', 'Budaya kerja Yayasan Pendidikan Sekolah Fammi periode ini paling terasa di sisi Kekeluargaan (67,8 poin), dan Tim tidak meminta itu berubah banyak. Yang paling jauh dari harapan adalah ruang mencoba hal baru: Inovasi dirasakan 47,5 poin sementara harapannya 68,7 poin, selisih +21,2 poin dan yang terbesar dari empat tipe. Di sisi lain Aturan justru dirasa berlebih, harapannya 9,6 poin di bawah kondisi sekarang. Dari sisi kesejahteraan, Kenyamanan Bekerja jadi modal terkuat (78 poin) sementara Work-Life Balance paling tertekan (48,7 poin), sejalan dengan jawaban esai yang berulang menyebut koreksi dan laporan yang terbawa sampai rumah.', array['School Culture'], 'Data demo 150 responden dari enam unit. Perbedaan antarunit cukup tajam: TK dan SD condong Kekeluargaan dengan kesejahteraan di atas rata-rata, SMP dan SMA condong Aturan/Orientasi dengan Work-Life Balance paling rendah. Kalau dipakai untuk demo, mulai dari section 01 (Budaya Kerja) lalu 02 (Kesejahteraan Tim) supaya alur ceritanya nyambung.', '[{"tema":"Dukungan antarrekan sebagai penopang utama","ringkasan":"Alasan paling sering disebut untuk tetap bertahan adalah rekan kerja yang saling menutup dan mudah diajak berdiskusi. Ini kekuatan yang menopang saat hal lain terasa berat.","jumlah_mention":104},{"tema":"Pekerjaan yang terbawa sampai rumah","ringkasan":"Koreksi dan laporan yang dikerjakan di rumah muncul di banyak jawaban, sejalan dengan Work-Life Balance sebagai subdimensi kesejahteraan paling rendah periode ini.","jumlah_mention":85},{"tema":"Ruang belajar dan kejelasan jenjang karier","ringkasan":"Permintaan pelatihan yang merata dan kejelasan jenjang karier muncul berulang, sejalan dengan Pengembangan Diri yang berada di kategori Sedang.","jumlah_mention":79},{"tema":"Kepastian jadwal dan kejelasan keputusan","ringkasan":"Jadwal kegiatan yang muncul mendadak dan rapat yang berakhir tanpa keputusan disebut membuat persiapan mengajar terganggu, bukan karena beban kerjanya berat, tapi karena tidak bisa direncanakan.","jumlah_mention":72},{"tema":"Beban administrasi di luar jam mengajar","ringkasan":"Pekerjaan administrasi yang formatnya berubah dan menumpuk di akhir bulan berulang kali disebut sebagai penguras energi utama, terutama oleh guru yang juga memegang tugas tambahan.","jumlah_mention":50},{"tema":"Keputusan yang dijelaskan alasannya","ringkasan":"Staf menghargai pimpinan yang mau mendengar, dan meminta keputusan penting disertai alasannya, bukan cuma diumumkan.","jumlah_mention":41},{"tema":"Murid sebagai sumber makna kerja","ringkasan":"Sebagian staf menyebut murid dan kepercayaan mengelola kelas sebagai alasan utama bertahan, terlepas dari beban kerja yang ada.","jumlah_mention":19}]'::jsonb, '{"gambaran_lembaga":[{"frasa":"Titipan harapan orang tua","jumlah_mention":19},{"frasa":"Kompak saat acara besar","jumlah_mention":18},{"frasa":"Keluarga besar","jumlah_mention":16},{"frasa":"Ramai tapi menyenangkan","jumlah_mention":15},{"frasa":"Hangat tapi padat","jumlah_mention":14},{"frasa":"Rapi tapi jarang dievaluasi","jumlah_mention":13},{"frasa":"Jalan terus tanpa berhenti","jumlah_mention":11},{"frasa":"Ruang belajar bersama","jumlah_mention":11},{"frasa":"Rumah kedua","jumlah_mention":10},{"frasa":"Aman, kurang ruang mencoba","jumlah_mention":10},{"frasa":"Tertib tapi kaku","jumlah_mention":9},{"frasa":"Rapi dan terjadwal","jumlah_mention":4}],"saat_ini":[{"frasa":"Briefing Senin pagi","jumlah_mention":16},{"frasa":"Tukar bahan ajar","jumlah_mention":15},{"frasa":"Ide berhenti di forum","jumlah_mention":14},{"frasa":"Pengumuman mendadak","jumlah_mention":14},{"frasa":"Saling menutup jam kosong","jumlah_mention":14},{"frasa":"Pendampingan guru baru","jumlah_mention":13},{"frasa":"Kasus murid dibahas bersama","jumlah_mention":12},{"frasa":"Sambutan pagi di gerbang","jumlah_mention":12},{"frasa":"Rapat sering molor","jumlah_mention":11},{"frasa":"Administrasi menumpuk","jumlah_mention":11},{"frasa":"Turun tangan sampai malam","jumlah_mention":10},{"frasa":"Istirahat dipakai koreksi","jumlah_mention":8}],"ingin_diubah":[{"frasa":"Kejelasan jenjang karier","jumlah_mention":18},{"frasa":"Jam pulang dihormati","jumlah_mention":18},{"frasa":"Waktu untuk metode baru","jumlah_mention":17},{"frasa":"Evaluasi rutin","jumlah_mention":14},{"frasa":"Pelatihan lebih merata","jumlah_mention":14},{"frasa":"Beban administrasi dikurangi","jumlah_mention":14},{"frasa":"Tugas tambahan lebih merata","jumlah_mention":13},{"frasa":"Keputusan dijelaskan alasannya","jumlah_mention":11},{"frasa":"Jadwal dipetakan lebih awal","jumlah_mention":11},{"frasa":"Jalur ide diperjelas","jumlah_mention":7},{"frasa":"Rapat lebih singkat","jumlah_mention":7},{"frasa":"Kolaborasi lintas jenjang","jumlah_mention":6}]}'::jsonb, 'excel');

-- ── 2.3 Tindak lanjut lembaga (9 dimensi, target_role yayasan) ────────────────────────
-- Sembilan baris menutup keempat tipe budaya dan kelima subdimensi kesejahteraan, jadi
-- tiap kartu dimensi di section 01-C dan 02-C punya isi, bukan empty-state. Kolom dimensi
-- diisi kode PERSIS yang dicocokkan cocokkanTlKeLabel() di useScData.js.
-- Cuma role 'yayasan' yang diseed karena cuma akun Yayasan yang dibuat di bagian 5. Kalau
-- nanti ditambah akun Kepala Sekolah atau Manajemen untuk lembaga ini, generate tindak
-- lanjutnya lewat CMS seperti biasa, jangan menyalin baris ini dengan target_role berbeda.
insert into public.tindak_lanjut (sekolah_id, modul, scope, scope_id, periode_id, target_role, term, type, fokus, dimensi, icon, title, teaser, mengapa_data, mengapa_perspektif, dasar_teori, manfaat, konkret, indikator_keberhasilan, hal_diwaspadai, action, trigger_desc, priority, draf_asal, status) values
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'long', 'perlu_perhatian', 'budaya', 'Inovasi', '💡', 'Buka ruang uji coba metode mengajar yang terjadwal, bukan insidental', 'Inovasi jadi jarak terbesar antara kondisi sekarang dan harapan Tim, +21,2 poin.', 'Inovasi dirasakan 47,5 dari 100 sementara harapannya 68,7, selisih +21,2 poin dan yang terbesar di antara empat tipe budaya. Pola yang sama muncul di jawaban esai: ide baru disebut sering berhenti di forum karena tidak jelas siapa yang memutuskan.', 'Guru jarang kekurangan ide. Yang biasanya kurang adalah waktu yang benar-benar dialokasikan untuk mencoba, dan kepastian bahwa percobaan yang gagal tidak akan dihitung sebagai kesalahan.', 'Psychological safety (Edmondson): tim berani mencoba hal baru saat risiko sosial dari kegagalan kecil dilihat rendah, bukan saat diminta lebih kreatif.', '{"tim":"Guru punya tempat yang jelas untuk mencoba tanpa merasa mencuri waktu dari kewajiban lain.","pimpinan":"Ide yang selama ini berhenti di forum jadi terlihat, lengkap dengan hasilnya.","sekolah":"Praktik mengajar yang terbukti bisa disebarkan antarjenjang, bukan berhenti di satu kelas."}'::jsonb, '[{"aksi":"Tetapkan satu hari per bulan sebagai waktu uji coba metode ajar, masuk kalender akademik.","waktu":"Bulan ini","kenapa":"Tanpa slot di kalender, uji coba selalu kalah dari kegiatan yang sudah terjadwal."},{"aksi":"Buat satu formulir usulan setengah halaman: ide, kelas sasaran, cara menilai hasilnya.","waktu":"Bulan ini","kenapa":"Jalur yang sederhana menutup alasan paling sering muncul, yaitu tidak tahu harus mengajukan ke siapa."},{"aksi":"Tunjuk satu penanggung jawab per jenjang yang berwenang menyetujui uji coba skala kelas.","waktu":"Bulan ini","kenapa":"Ide berhenti bukan karena ditolak, tapi karena tidak ada yang merasa berwenang memutuskan."},{"aksi":"Bahas hasil uji coba di forum jenjang tiap akhir bulan, termasuk yang tidak berhasil.","waktu":"3 bulan","kenapa":"Membahas yang gagal secara terbuka adalah cara tercepat menurunkan rasa takut mencoba."}]'::jsonb, '[{"title":"Jumlah uji coba tercatat","detail":"Berapa uji coba metode ajar yang benar-benar dijalankan dan dilaporkan tiap bulan per jenjang."},{"title":"Sebaran pengusul","detail":"Berapa guru berbeda yang mengajukan, bukan orang yang sama berulang kali."},{"title":"Praktik yang diadopsi ulang","detail":"Berapa metode hasil uji coba yang dipakai guru lain di semester berikutnya."}]'::jsonb, '["Kalau waktu uji coba diumumkan tapi tidak mengurangi beban lain, guru akan membacanya sebagai tugas tambahan, bukan ruang.","Kalau cuma percobaan yang berhasil yang diapresiasi, guru akan berhenti melaporkan yang gagal dan datanya jadi tidak berguna."]'::jsonb, 'Buka ruang uji coba metode mengajar yang terjadwal, bukan insidental', 'Inovasi jadi jarak terbesar antara kondisi sekarang dan harapan Tim, +21,2 poin.', 'tinggi', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'short', 'perlu_perhatian', 'budaya', 'Aturan', '📋', 'Pangkas prosedur yang tidak lagi menambah nilai', 'Aturan dirasakan 63,1 poin, lebih tinggi dari yang diharapkan Tim (53,5).', 'Aturan satu-satunya tipe budaya yang harapannya LEBIH RENDAH dari kondisi sekarang, selisih -9,6 poin. Artinya bukan ketertiban yang kurang, tapi porsinya sudah melewati yang dibutuhkan Tim untuk bekerja.', 'Prosedur biasanya bertambah karena ada masalah yang perlu ditutup, dan hampir tidak pernah dikurangi saat masalahnya sudah lewat. Yang menumpuk kemudian dibaca staf sebagai ketidakpercayaan.', 'Job Demands-Resources: tuntutan administratif yang tidak berujung pada hasil kerja terbaca sebagai beban murni, bukan sumber daya, dan berkorelasi langsung dengan kelelahan kerja.', '{"tim":"Waktu yang selama ini habis di formulir kembali ke persiapan mengajar.","pimpinan":"Prosedur yang tersisa lebih mungkin benar-benar dijalankan, bukan dilewati diam-diam.","sekolah":"Kecepatan mengambil keputusan naik tanpa harus menambah orang."}'::jsonb, '[{"aksi":"Daftar semua laporan rutin yang wajib diisi guru satu semester terakhir, lengkap dengan siapa yang membacanya.","waktu":"Minggu ini","kenapa":"Laporan yang tidak punya pembaca adalah kandidat pertama untuk dihapus."},{"aksi":"Hapus atau gabungkan minimal tiga laporan yang datanya sudah ada di tempat lain.","waktu":"Bulan ini","kenapa":"Target angka yang jelas mencegah audit prosedur berhenti jadi wacana."},{"aksi":"Tetapkan aturan main baru: setiap prosedur baru wajib menyebut prosedur mana yang digantikannya.","waktu":"3 bulan","kenapa":"Tanpa aturan pengganti, jumlah prosedur cuma akan bertambah lagi setelah audit ini."}]'::jsonb, '[{"title":"Jumlah laporan rutin","detail":"Berapa laporan wajib guru sebelum dan sesudah audit, dihitung per semester."},{"title":"Jam administrasi per guru","detail":"Perkiraan jam per bulan yang dipakai untuk administrasi, ditanyakan langsung ke guru."}]'::jsonb, '["Kalau prosedur dipangkas tanpa memperjelas siapa yang bertanggung jawab, yang muncul bukan kelegaan tapi kebingungan baru."]'::jsonb, 'Pangkas prosedur yang tidak lagi menambah nilai', 'Aturan dirasakan 63,1 poin, lebih tinggi dari yang diharapkan Tim (53,5).', 'tinggi', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'long', 'pertahankan', 'budaya', 'Kekeluargaan', '🤝', 'Jaga kekuatan kekeluargaan supaya tidak habis untuk menambal jadwal', 'Kekeluargaan jadi budaya paling terasa (67,8 poin) dan harapannya cuma +3,7 poin di atasnya.', 'Kekeluargaan tertinggi di antara empat tipe (67,8 poin) dengan selisih harapan cuma +3,7 poin, jadi ini modal yang sudah jalan. Jawaban esai menguatkannya: saling menutup jam mengajar rekan yang berhalangan disebut berulang sebagai kebiasaan sehari-hari.', 'Kebiasaan saling menutup adalah kekuatan sekaligus risiko. Kalau dipakai terus untuk menambal jadwal yang berubah mendadak, yang tersisa adalah kelelahan yang tidak pernah tercatat sebagai masalah organisasi.', 'Modal sosial organisasi (Nahapiet & Ghoshal): kepercayaan antaranggota mempercepat kerja, tapi terkuras kalau terus dipakai menutup kegagalan sistem.', '{"tim":"Bantuan antarrekan tetap terasa sukarela, bukan kewajiban tak tertulis.","pimpinan":"Kelelahan yang selama ini tertutup gotong royong jadi terlihat lebih awal.","sekolah":"Kekuatan budaya ini bertahan lintas pergantian orang, bukan bergantung pada beberapa guru senior."}'::jsonb, '[{"aksi":"Catat setiap penggantian jam mengajar dadakan selama satu bulan, siapa yang menutup dan berapa kali.","waktu":"Bulan ini","kenapa":"Beban yang jatuh berulang ke orang yang sama biasanya baru terlihat setelah dihitung."},{"aksi":"Batasi jumlah penggantian dadakan per guru per bulan, sisanya jadi tanggung jawab jadwal.","waktu":"3 bulan","kenapa":"Batas yang jelas memindahkan masalah ke tempat yang benar, yaitu perencanaan jadwal."},{"aksi":"Sebut nama guru yang membantu di forum unit, bukan cuma di grup pesan.","waktu":"Minggu ini","kenapa":"Pengakuan yang terlihat menjaga kebiasaan ini tetap hidup tanpa perlu insentif baru."}]'::jsonb, '[{"title":"Sebaran penggantian jam","detail":"Berapa guru berbeda yang menutup jam kosong, dibanding jumlah penggantian total."},{"title":"Penggantian dadakan per bulan","detail":"Tren jumlah penggantian dadakan setelah jadwal dipetakan lebih awal."}]'::jsonb, '["Kalau penggantian dadakan dibatasi tanpa memperbaiki perencanaan jadwal, kelas yang kosong justru bertambah."]'::jsonb, 'Jaga kekuatan kekeluargaan supaya tidak habis untuk menambal jadwal', 'Kekeluargaan jadi budaya paling terasa (67,8 poin) dan harapannya cuma +3,7 poin di atasnya.', 'sedang', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'short', 'pertahankan', 'budaya', 'Orientasi', '🎯', 'Pertahankan arah capaian yang sudah selaras dengan harapan Tim', 'Orientasi capaian dirasakan 56,1 poin, praktis sama dengan harapan Tim (56,9).', 'Selisih Orientasi cuma +0,7 poin, paling kecil di antara empat tipe. Tim tidak meminta target dikurangi maupun ditambah, jadi tugas periode ini menjaga, bukan mengubah.', 'Dimensi yang sudah selaras paling sering luput dari perhatian karena tidak menimbulkan keluhan. Padahal keselarasan itu yang membuat perbaikan di dimensi lain punya pijakan.', 'Goal-setting theory (Locke & Latham): target yang disepakati dan terukur menaikkan kinerja, sepanjang orang yang menjalankan ikut menentukannya.', '{"tim":"Ukuran keberhasilan tetap jelas dan tidak berubah di tengah semester.","pimpinan":"Ada satu dimensi stabil yang bisa dipakai sebagai pembanding saat menilai perubahan di dimensi lain.","sekolah":"Fokus akademik terjaga sementara perbaikan budaya berjalan."}'::jsonb, '[{"aksi":"Umumkan ulang ukuran keberhasilan tiap unit di awal semester, tanpa menambah indikator baru.","waktu":"Bulan ini","kenapa":"Keselarasan bertahan kalau ukurannya diingatkan, bukan diasumsikan sudah dipahami."},{"aksi":"Tinjau capaian tiap unit satu kali di tengah semester, bukan cuma di akhir.","waktu":"3 bulan","kenapa":"Tinjauan di tengah masih menyisakan waktu untuk memperbaiki, tinjauan akhir cuma mencatat."},{"aksi":"Sertakan alasan di balik setiap target yang diumumkan.","waktu":"Bulan ini","kenapa":"Target yang jelas alasannya lebih mungkin dijalankan tanpa pengawasan tambahan."}]'::jsonb, '[{"title":"Kesamaan pemahaman target","detail":"Berapa persen staf yang bisa menyebut ukuran keberhasilan unitnya saat ditanya di tengah semester."}]'::jsonb, '["Kalau target ditambah dengan alasan hasil survei sudah baik, keselarasan yang sekarang ada bisa hilang dalam satu periode."]'::jsonb, 'Pertahankan arah capaian yang sudah selaras dengan harapan Tim', 'Orientasi capaian dirasakan 56,1 poin, praktis sama dengan harapan Tim (56,9).', 'sedang', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'short', 'perlu_perhatian', 'kesejahteraan', 'work_life_balance', '⚖️', 'Kembalikan batas jam kerja yang sekarang terbawa sampai rumah', 'Work-Life Balance jadi subdimensi kesejahteraan terendah, 48,7 poin.', 'Work-Life Balance 48,7 poin, terendah dari lima subdimensi dan jauh di bawah Kenyamanan Bekerja (78). Butir yang paling menekan adalah waktu istirahat yang habis dikejar pekerjaan, dan jawaban esai menyebut koreksi serta laporan yang dibawa pulang hampir tiap malam.', 'Staf yang merasa nyaman dengan rekan kerjanya sering bertahan jauh lebih lama sebelum mengeluh soal beban. Angka kenyamanan yang tinggi bersamaan dengan keseimbangan yang rendah biasanya menandakan kelelahan yang ditanggung diam-diam.', 'Effort-Recovery Model (Meijman & Mulder): pemulihan hanya terjadi kalau tuntutan kerja benar-benar berhenti untuk periode tertentu, bukan sekadar berkurang.', '{"tim":"Ada jam yang bisa benar-benar dipakai untuk berhenti, tanpa rasa bersalah.","pimpinan":"Risiko kelelahan kerja terbaca sebelum berubah jadi pengunduran diri.","sekolah":"Kualitas mengajar terjaga karena pemulihan guru tidak lagi bergantung pada libur panjang."}'::jsonb, '[{"aksi":"Sepakati jam malam tanpa pesan pekerjaan di semua grup unit, dimulai dari pimpinan.","waktu":"Minggu ini","kenapa":"Batas yang dilanggar pimpinan tidak akan pernah dianggap berlaku oleh staf."},{"aksi":"Sediakan dua slot koreksi di jam sekolah per pekan untuk guru kelas.","waktu":"Bulan ini","kenapa":"Koreksi terbawa pulang karena tidak punya tempat di jadwal, bukan karena jumlahnya mustahil."},{"aksi":"Hitung ulang beban tugas tambahan per guru, ratakan yang menumpuk di orang yang sama.","waktu":"3 bulan","kenapa":"Jawaban esai berulang kali menyebut tugas tambahan jatuh ke orang yang itu-itu saja."}]'::jsonb, '[{"title":"Pesan kerja di luar jam","detail":"Jumlah pesan pekerjaan yang dikirim setelah jam yang disepakati, dipantau per unit."},{"title":"Skor Work-Life Balance","detail":"Nilai subdimensi ini di periode asesmen berikutnya, dibanding angka sekarang."},{"title":"Sebaran tugas tambahan","detail":"Berapa guru memegang lebih dari dua tugas tambahan sekaligus."}]'::jsonb, '["Kalau jam malam disepakati tapi tenggat tetap tidak berubah, staf cuma memindahkan pekerjaannya ke subuh.","Kalau slot koreksi diambil dari jam istirahat, angka keseimbangan tidak akan bergerak sama sekali."]'::jsonb, 'Kembalikan batas jam kerja yang sekarang terbawa sampai rumah', 'Work-Life Balance jadi subdimensi kesejahteraan terendah, 48,7 poin.', 'tinggi', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'long', 'perlu_perhatian', 'kesejahteraan', 'pengembangan_diri', '📚', 'Ratakan kesempatan belajar dan perjelas jenjangnya', 'Pengembangan Diri 55,6 poin, dengan butir jalur karier sebagai yang terendah.', 'Pengembangan Diri berada di 55,6 poin, dan butir tentang kejelasan jalur karier jadi yang paling rendah di dalamnya. Permintaan agar pelatihan tidak bergilir ke orang yang sama muncul berulang di jawaban esai.', 'Guru jarang meminta pelatihan mahal. Yang lebih sering diminta adalah kepastian bahwa kesempatan itu ada gilirannya, dan bahwa usaha berkembang punya arah yang jelas.', 'Self-Determination Theory: kebutuhan akan kompetensi dan pertumbuhan adalah pendorong motivasi bertahan yang bekerja terpisah dari kompensasi.', '{"tim":"Kesempatan belajar terasa bisa diakses, bukan bergantung kedekatan dengan pimpinan.","pimpinan":"Rencana pengembangan staf punya dasar, bukan menjawab permintaan satu per satu.","sekolah":"Kaderisasi berjalan tanpa perlu rekrutmen mendadak saat ada yang keluar."}'::jsonb, '[{"aksi":"Buat daftar terbuka siapa yang sudah dan belum ikut pelatihan dua tahun terakhir.","waktu":"Bulan ini","kenapa":"Ketimpangan giliran biasanya tidak disengaja dan baru terlihat setelah didaftar."},{"aksi":"Tetapkan kuota minimal satu kesempatan belajar per guru per tahun, termasuk pelatihan internal.","waktu":"3 bulan","kenapa":"Kuota membuat pemerataan jadi kewajiban perencanaan, bukan kebaikan hati."},{"aksi":"Tuliskan tahapan peran yang mungkin ditempuh guru dan tenaga kependidikan di lembaga ini.","waktu":"3 bulan","kenapa":"Jenjang karier yang tidak pernah ditulis akan selalu terbaca sebagai tidak ada."}]'::jsonb, '[{"title":"Cakupan pelatihan","detail":"Persentase staf yang mengikuti minimal satu kegiatan pengembangan dalam setahun."},{"title":"Kejelasan jenjang","detail":"Berapa staf yang bisa menyebutkan tahapan peran berikutnya saat ditanya."}]'::jsonb, '["Kalau jenjang karier ditulis tapi tidak pernah dipakai saat mengisi posisi kosong, kepercayaan yang hilang lebih besar daripada sebelum ditulis."]'::jsonb, 'Ratakan kesempatan belajar dan perjelas jenjangnya', 'Pengembangan Diri 55,6 poin, dengan butir jalur karier sebagai yang terendah.', 'tinggi', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'short', 'perlu_perhatian', 'kesejahteraan', 'kepuasan_kepemimpinan', '🗣️', 'Jelaskan alasan di balik keputusan, bukan cuma hasilnya', 'Kepuasan pada Kepemimpinan 62,4 poin, ditekan butir keterbukaan informasi.', 'Kepuasan pada Kepemimpinan berada di 62,4 poin, dengan butir keterbukaan informasi sebagai yang terendah dari tiga butirnya. Jawaban esai menyebut pengumuman kegiatan yang datang mendadak dan keputusan yang tidak jelas dasarnya.', 'Staf yang tidak tahu alasan sebuah keputusan akan mengisi kekosongan itu dengan dugaan sendiri. Menjelaskan alasan biasanya lebih murah daripada memperbaiki dugaan yang sudah menyebar.', 'Keadilan prosedural (Colquitt): persepsi keadilan lebih ditentukan oleh transparansi proses pengambilan keputusan daripada oleh hasil keputusannya sendiri.', '{"tim":"Keputusan lebih mudah diterima meski tidak semuanya menyenangkan.","pimpinan":"Waktu yang habis menjawab pertanyaan susulan berkurang.","sekolah":"Perubahan kebijakan berjalan lebih cepat karena tidak tertahan resistensi diam."}'::jsonb, '[{"aksi":"Sertakan tiga kalimat alasan pada setiap pengumuman kebijakan baru.","waktu":"Minggu ini","kenapa":"Alasan yang menempel di pengumuman menutup jarak sebelum dugaan sempat terbentuk."},{"aksi":"Umumkan kalender kegiatan minimal satu bulan sebelumnya, dengan batas waktu penambahan.","waktu":"Bulan ini","kenapa":"Keluhan mendadak paling sering soal jadwal, bukan soal isi kebijakannya."},{"aksi":"Sediakan forum singkat per unit tiap bulan yang agendanya dibuka dari staf.","waktu":"3 bulan","kenapa":"Forum yang agendanya ditentukan pimpinan tidak akan pernah memunculkan keluhan yang sebenarnya."}]'::jsonb, '[{"title":"Jarak pengumuman","detail":"Rata-rata berapa hari sebelum pelaksanaan sebuah kegiatan diumumkan."},{"title":"Partisipasi forum unit","detail":"Berapa staf berbeda yang menyampaikan hal di forum bulanan."}]'::jsonb, '["Kalau forum dibuka tapi masukan yang masuk tidak pernah ditindaklanjuti, kepuasan bisa turun lebih jauh daripada sebelum ada forum."]'::jsonb, 'Jelaskan alasan di balik keputusan, bukan cuma hasilnya', 'Kepuasan pada Kepemimpinan 62,4 poin, ditekan butir keterbukaan informasi.', 'tinggi', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'long', 'pertahankan', 'kesejahteraan', 'ekspektasi', '🌤️', 'Jaga kesesuaian antara yang dijanjikan dan yang dijalani', 'Ekspektasi Terpenuhi 65,2 poin, ditopang butir harapan awal yang terpenuhi.', 'Ekspektasi Terpenuhi berada di 65,2 poin. Butir harapan awal bekerja jadi yang tertinggi, sementara butir penghargaan yang sepadan tertinggal di bawahnya.', 'Kesesuaian antara janji saat rekrutmen dan kenyataan kerja adalah salah satu penentu terkuat orang bertahan. Yang menggerusnya biasanya bukan satu peristiwa besar, tapi penambahan tugas yang tidak pernah dibicarakan ulang.', 'Psychological contract (Rousseau): pelanggaran kesepakatan tak tertulis antara staf dan lembaga menurunkan komitmen lebih cepat daripada ketidakpuasan pada gaji.', '{"tim":"Perubahan peran dibicarakan, bukan diberitahukan setelah berjalan.","pimpinan":"Alasan sebenarnya orang bertahan atau keluar jadi terbaca lebih awal.","sekolah":"Perputaran staf tetap rendah tanpa perlu menaikkan biaya."}'::jsonb, '[{"aksi":"Tinjau ulang uraian tugas yang sudah berubah di lapangan tapi belum diperbarui di dokumen.","waktu":"Bulan ini","kenapa":"Jarak antara dokumen dan kenyataan adalah tempat kekecewaan tumbuh diam-diam."},{"aksi":"Bicarakan penambahan tugas tambahan sebelum ditetapkan, bukan lewat pengumuman.","waktu":"Bulan ini","kenapa":"Tugas yang disepakati ditanggung berbeda dengan tugas yang diterima."},{"aksi":"Adakan percakapan singkat setahun sekali soal harapan staf pada perannya.","waktu":"3 bulan","kenapa":"Harapan yang tidak pernah ditanyakan cuma terdengar saat orangnya sudah memutuskan pergi."}]'::jsonb, '[{"title":"Kesesuaian uraian tugas","detail":"Berapa uraian tugas yang diperbarui agar cocok dengan pekerjaan sebenarnya."},{"title":"Perputaran staf","detail":"Jumlah staf yang keluar per tahun dibanding periode sebelumnya."}]'::jsonb, '["Kalau percakapan harapan dilakukan tapi tidak ada satu pun yang ditindaklanjuti, staf akan berhenti menjawab jujur di periode berikutnya."]'::jsonb, 'Jaga kesesuaian antara yang dijanjikan dan yang dijalani', 'Ekspektasi Terpenuhi 65,2 poin, ditopang butir harapan awal yang terpenuhi.', 'sedang', 'excel', 'disetujui'),
('YPS-FAMMI', 'sc', 'sekolah', 'YPS-FAMMI', '2026-07', 'yayasan', 'long', 'pertahankan', 'kesejahteraan', 'kenyamanan_bekerja', '🫱', 'Rawat kenyamanan kerja sebagai modal paling kuat lembaga ini', 'Kenyamanan Bekerja 78 poin, tertinggi dari lima subdimensi.', 'Kenyamanan Bekerja 78 poin, tertinggi dari lima subdimensi dan terpaut jauh dari Work-Life Balance (48,7). Alasan bertahan yang paling sering disebut di esai adalah rekan kerja yang mudah diajak berdiskusi dan saling menutup saat berhalangan.', 'Kenyamanan yang tinggi bisa menutupi masalah lain cukup lama. Merawatnya berarti memastikan ia tidak jadi satu-satunya alasan orang bertahan.', 'Job Embeddedness (Mitchell): keterikatan pada rekan kerja adalah penahan terkuat keputusan pindah kerja, sering melampaui faktor kompensasi.', '{"tim":"Suasana yang sekarang jadi alasan bertahan tidak terkikis oleh pergantian orang.","pimpinan":"Staf baru lebih cepat menyatu, bukan bertahan sendirian di bulan pertama.","sekolah":"Reputasi sebagai tempat kerja yang baik jadi aset rekrutmen."}'::jsonb, '[{"aksi":"Tetapkan pendamping resmi untuk setiap staf baru selama tiga bulan pertama.","waktu":"Bulan ini","kenapa":"Kebiasaan menemani guru baru sudah ada, tinggal dipastikan tidak bergantung inisiatif orang per orang."},{"aksi":"Jadwalkan satu pertemuan lintas unit per semester dengan agenda berbagi praktik.","waktu":"3 bulan","kenapa":"Kenyamanan sekarang kuat di dalam unit, tapi belum menyeberang antarjenjang."},{"aksi":"Tanyakan pengalaman tiga bulan pertama ke setiap staf baru dan catat hasilnya.","waktu":"3 bulan","kenapa":"Titik lemah penyambutan paling jelas terlihat dari orang yang baru saja melewatinya."}]'::jsonb, '[{"title":"Pendampingan staf baru","detail":"Persentase staf baru yang punya pendamping resmi dan bertemu rutin."},{"title":"Interaksi lintas unit","detail":"Berapa kegiatan yang melibatkan lebih dari satu unit per semester."}]'::jsonb, '["Kalau pendampingan dijadikan tugas tambahan tanpa pengurangan beban lain, guru senior yang selama ini sukarela justru berhenti melakukannya."]'::jsonb, 'Rawat kenyamanan kerja sebagai modal paling kuat lembaga ini', 'Kenyamanan Bekerja 78 poin, tertinggi dari lima subdimensi.', 'sedang', 'excel', 'disetujui')
